#include "NativeHierarchyListAot.generated.h"
#include "NativeHierarchyItemAot.generated.h"
#include "NativeHierarchyCountAot.generated.h"
#include "NativeHierarchyDelegateAot.generated.h"
#include <iiGUI/WidgetState.h>
#include <iostream>
using namespace ii;
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class T>T take(core::Result<T> r){if(!r){if(r.error().cause)std::rethrow_exception(r.error().cause);throw std::runtime_error(r.error().message);}return std::move(*r);}
void good(core::Result<void> r){if(!r){if(r.error().cause)std::rethrow_exception(r.error().cause);throw std::runtime_error(r.error().message);}}
template<class View>struct Mounted final {
    std::shared_ptr<gui::detail::WidgetState> tree=std::make_shared<gui::detail::WidgetState>([](runtime::Task task){task();});gui::Widget host=take(tree->content_host({},"host",{480,500}));std::shared_ptr<typename View::Scope> scope;
    Mounted(){good(host.set_content([&](gui::WidgetBuilder& b){return View::build(b,{}, {},&scope);}));}
    ~Mounted(){tree->close();scope.reset();}
    gui::Widget find(std::string_view suffix){for(const auto& n:take(tree->snapshots()))if(n.id.ends_with(suffix))return take(tree->find(n.id));throw std::runtime_error("Missing generated hierarchy widget");}
    std::string text(std::string_view suffix){return take(find(suffix).snapshot()).text;}
    void click(std::string_view suffix){good(find(suffix).activate());}
    gui::Widget row(std::string_view title){for(const auto& node:take(tree->snapshots()))if(node.id.ends_with("/row")&&node.accessibility_name==title)return take(tree->find(node.id));throw std::runtime_error("Missing generated delegate row");}
};
using List=lvui_generated::NativeHierarchyListAot;using Item=lvui_generated::NativeHierarchyItemAot;
using Count=lvui_generated::NativeHierarchyCountAot;
using Delegate=lvui_generated::NativeHierarchyDelegateAot;
void list(){Mounted<List> m;check(m.text("/active")=="root","Native hierarchy initial state did not reach generated bindings");m.click("/image");check(m.text("/active")=="image"&&take(m.scope->backend_0.controller->state()).visible_count==4&&m.scope->backend_0.activations==1,"Generated command did not select and reveal a hidden layer");}
void external(){Mounted<List> m;take(m.scope->backend_0.controller->activate_by_key("other"));check(m.text("/active")=="other","External native selection did not refresh the compiled view");}
void height(){Mounted<List> m;m.click("/image");const auto revision=take(m.scope->backend_0.model->state()).revision;m.click("/compact");check(take(m.scope->backend_0.controller->row_extent(0))==17&&take(m.scope->backend_0.controller->state()).content_extent==68&&take(m.scope->backend_0.model->state()).revision==revision,"Reactive row height did not update native projection or changed file-like data");}
void item(){Mounted<Item> m;auto root=m.find("/item");m.click("/item");check(m.scope->backend_0.activations==1&&m.scope->backend_0.selected.get()&&take(root.snapshot()).checked,"Generated hierarchy activation lost its native callback or selected input");m.click("item.chevron");check(m.scope->backend_0.expanded.get(),"Native chevron did not forward its typed Bool callback");}
void rename(){Mounted<Item> m;const auto id=take(m.find("/item").snapshot()).id;m.click("/rename");check(m.text("item.label")=="Renamed"&&m.text("item.count")=="3"&&take(m.find("/item").snapshot()).id==id,"Reactive item data reconstructed its native row or stayed stale");}
void nonmutation(){Mounted<List> m;auto& b=m.scope->backend_0;const auto revision=take(b.model->state()).revision;for(int i=0;i<10;++i){take(b.controller->activate_by_key("image"));take(b.controller->set_expanded("group",false));}check(take(b.model->state()).revision==revision&&b.file_revision.get()==0,"Compiled hierarchy view commands mutated document state");}
void retirement(){Mounted<List> m;auto c=m.scope->backend_0.controller;auto model=m.scope->backend_0.model;auto old=m.find("/tree");std::weak_ptr<typename List::Scope> weak=m.scope;good(m.host.clear_content());m.scope.reset();check(weak.expired()&&!old.snapshot(),"Generated hierarchy scope retained widgets after retirement");take(c->activate_by_key("other"));check(!take(model->state()).closed,"View retirement closed its external source");}
void source(){Mounted<List> m;auto& backend=m.scope->backend_0;auto old=backend.controller;const auto revision=take(backend.model->state()).revision;const auto root=take(m.find("/tree").snapshot()).id;m.click("/replace");check(m.text("/active")=="chosen"&&take(m.find("/tree").snapshot()).id==root&&backend.activations==0,"A bound controller replacement lost native source identity or fabricated an activation event");take(old->activate_by_key("other"));check(m.text("/active")=="chosen","The old source still drove a replacement binding");m.click("/restore");check(m.text("/active")=="other"&&take(backend.model->state()).revision==revision&&backend.file_revision.get()==0,"Returning to a controller lost its own selection or mutated file state");}
void count_context(){Mounted<Count> m;check(m.text("/current")=="Layer:2"&&m.text("/initial")=="Layer:2"&&m.text("/owner")=="Same owner"&&NativeHierarchyCountLifetime::live==1,"Typed countView did not receive the owning row or activate its own import");m.click("/pick");check(m.scope->backend_0.activations==1,"A countView command lost its deferred row receiver or fired the parent twice");}
void count_updates(){Mounted<Count> m;const auto id=take(m.find("/private").snapshot()).id;good(m.find("/private").set_text("User input"));m.click("/rename");check(m.text("/current")=="Renamed:3"&&m.text("/initial")=="Layer:2"&&m.text("/private")=="User input"&&take(m.find("/private").snapshot()).id==id&&NativeHierarchyCountLifetime::created==1,"Row updates reconstructed countView, lost private state or froze live context");}
void count_lifetime(){Mounted<Count> m;auto old=m.find("/pick");m.click("/hide");check(NativeHierarchyCountLifetime::live==0&&!old.snapshot()&&!old.activate(),"A hidden countView retained imports or accepted a stale command");m.click("/show");check(NativeHierarchyCountLifetime::live==1&&NativeHierarchyCountLifetime::created==2&&m.text("/current")=="Layer:2","Count visibility did not create a fresh child activation");}
void count_retirement(){Mounted<Count> m;auto old=m.find("/private");std::weak_ptr<typename Count::Scope> weak=m.scope;good(m.host.clear_content());m.scope.reset();check(weak.expired()&&NativeHierarchyCountLifetime::live==0&&!old.snapshot(),"CountView imports, bindings or parent scope survived view retirement");}
void count_external(){Mounted<Count> m;m.scope->backend_0.label.set("External");check(m.text("/current")=="External:2"&&m.text("/initial")=="Layer:2"&&NativeHierarchyCountLifetime::created==1,"External C++ row state did not reach the retained countView through getter observation");}
void count_self_retirement(){Mounted<Count> m;auto old=m.find("/pick");m.scope->backend_0.hide_on_click=true;m.click("/pick");check(m.scope->backend_0.live_during_hide==1&&NativeHierarchyCountLifetime::live==0&&!old.snapshot(),"A self-removing countView destroyed its active imported receiver too early or retained it after return");}
void delegate_initial(){Mounted<Delegate> m;check(m.text("/active")=="k0"&&m.row("View Layer 0").snapshot()&&NativeHierarchyDelegateLifetime::live>0&&NativeHierarchyDelegateLifetime::live<20,"A native delegate did not inherit row data or was eagerly created for every source item");}
void delegate_state(){Mounted<Delegate> m;auto old=m.row("View Layer 0");good(m.row("View Layer 1").activate());check(take(m.scope->backend_0.controller->state()).active_key=="k1"&&m.scope->backend_0.activations==1&&take(m.row("View Layer 1").snapshot()).checked&&!take(old.snapshot()).checked,"A delegate replaced list selection, duplicated activation or froze selected input");}
void delegate_data(){Mounted<Delegate> m;auto& backend=m.scope->backend_0;auto old=m.row("View Layer 0");auto field=m.find("/private");const auto id=take(field.snapshot()).id;good(field.set_text("User"));const auto created=NativeHierarchyDelegateLifetime::created;auto row=take(backend.model->row("k0")).get();row.label="Updated";take(backend.model->update_row("k0",row));check(old.snapshot()&&m.row("View Updated").snapshot()&&NativeHierarchyDelegateLifetime::created==created&&take(field.snapshot()).id==id&&take(field.snapshot()).text=="User","A source label update lost delegate styling, input state or native row identity");}
void delegate_style(){Mounted<Delegate> m;auto old=m.row("View Layer 0");const auto created=NativeHierarchyDelegateLifetime::created;m.scope->backend_0.prefix.set("New ");m.scope->backend_0.padding.set(2);check(old.snapshot()&&m.row("New Layer 0").snapshot()&&NativeHierarchyDelegateLifetime::created==created,"A reactive delegate style recreated row scopes or was overwritten by list defaults");}
void delegate_count(){Mounted<Delegate> m;take(m.scope->backend_0.controller->activate_by_key("k1"));m.click("/count");check(m.scope->backend_0.count_actions==1&&m.scope->backend_0.last_key=="k0"&&take(m.scope->backend_0.controller->state()).active_key=="k1","A nested delegate count command lost its row or activated the parent");}
void delegate_scroll(){Mounted<Delegate> m;auto old=m.row("View Layer 0");const auto revision=take(m.scope->backend_0.model->state()).revision;good(m.find("content.viewport").set_scroll_offset(1000));check(!old.snapshot()&&NativeHierarchyDelegateLifetime::live>0&&NativeHierarchyDelegateLifetime::live<20&&take(m.scope->backend_0.model->state()).revision==revision,"Delegate virtualization retained offscreen generations or mutated source data");}
void delegate_retirement(){Mounted<Delegate> m;auto controller=m.scope->backend_0.controller;std::weak_ptr<typename Delegate::Scope> weak=m.scope;auto old=m.row("View Layer 0");good(m.host.clear_content());m.scope.reset();check(weak.expired()&&NativeHierarchyDelegateLifetime::live==0&&!old.snapshot()&&!take(controller->state()).closed,"Delegate retirement retained imports, input or source ownership");}
void delegate_replacement(){Mounted<Delegate> m;auto old=m.row("View Layer 0");m.scope->backend_0.replace();check(!old.snapshot()&&m.row("View New").snapshot()&&m.text("/active")=="new"&&NativeHierarchyDelegateLifetime::live==1,"A source replacement retained old delegate scopes or failed to inherit the new source");}
void delegate_failure(){Mounted<Delegate> m;auto& backend=m.scope->backend_0;auto old=m.row("View Layer 0");backend.bad_label.set(true);auto row=take(backend.model->row("k0")).get();row.label="Updated";auto result=backend.model->update_row("k0",row);check(!result&&old.snapshot()&&m.row("View Layer 0").snapshot(),"An invalid delegate projection was silently acknowledged or destroyed the last valid row");backend.bad_label.set(false);check(old.snapshot()&&m.row("View Updated").snapshot(),"A delegate did not recover through its retained failed-input dependency");}
}
int main(int argc,char** argv){try{const std::string n=argc>1?argv[1]:"list";if(n=="list")list();else if(n=="external")external();else if(n=="height")height();else if(n=="item")item();else if(n=="rename")rename();else if(n=="nonmutation")nonmutation();else if(n=="retirement")retirement();else if(n=="source")source();else if(n=="count_context")count_context();else if(n=="count_updates")count_updates();else if(n=="count_lifetime")count_lifetime();else if(n=="count_retirement")count_retirement();else if(n=="count_external")count_external();else if(n=="count_self_retirement")count_self_retirement();else if(n=="delegate_initial")delegate_initial();else if(n=="delegate_state")delegate_state();else if(n=="delegate_data")delegate_data();else if(n=="delegate_style")delegate_style();else if(n=="delegate_count")delegate_count();else if(n=="delegate_scroll")delegate_scroll();else if(n=="delegate_retirement")delegate_retirement();else if(n=="delegate_replacement")delegate_replacement();else if(n=="delegate_failure")delegate_failure();else throw std::runtime_error("Unknown hierarchy AOT case");std::cout<<"Native hierarchy AOT "<<n<<" passed\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
